export function cellsForDistrict(district: string): string[] {
  if (!district) return []
  return DISTRICT_CELLS[district] ?? []
}

/** Geographic Sector (NEP) — same as legacy `cellsForDistrict` name in older code. */
export function sectorsForDistrict(district: string): string[] {
  return cellsForDistrict(district)
}

export function cellulesForDistrictSector(district: string, sector: string): string[] {
  if (!district || !sector) return []
  return SECTOR_CELLULES[JSON.stringify([district, sector])] ?? []
}

export function villagesForDistrictSectorCellule(district: string, sector: string, cellule: string): string[] {
  if (!district || !sector || !cellule) return []
  return CELLULE_VILLAGES[JSON.stringify([district, sector, cellule])] ?? []
}
